import json

def list_skills():
    return execute_tool('ToolsetRegistry.AgentSkillToolset.ListSkills', '{}')['returnValue']

def create_skill(name, description, instructions):
    return execute_tool('ToolsetRegistry.AgentSkillToolset.CreateSkill', json.dumps({'folderPath': '/ExtractionOps/Skills/', 'assetName': name, 'description': description, 'details': {'instructions': instructions}}))['returnValue']

def update_skill(path, description, instructions):
    return execute_tool('ToolsetRegistry.AgentSkillToolset.UpdateSkill', json.dumps({'skillPath': path, 'description': description, 'details': {'instructions': instructions}}))['returnValue']

def save(paths):
    return execute_tool('editor_toolset.toolsets.asset.AssetTools.save_assets', json.dumps({'asset_paths': paths}))['returnValue']

def get_skills(paths):
    return execute_tool('ToolsetRegistry.AgentSkillToolset.GetSkills', json.dumps({'skillPaths': paths}))['returnValue']

def run():
    specs = {
      'ExtractionOpsAssetAuthoring': ('Author and verify Extraction Ops assets without bypassing Unreal serialization.', 'Use the live Unreal Editor MCP connection. Discover toolsets and inspect real classes/properties before editing. Keep one B_ExtractionExperience and one ExtractionOps GameFeatureData. Reuse Lyra Character, ASC, movement, animation, Inventory, Equipment, QuickBar and ranged TargetData; C++ owns rules, authority and replication while assets/Blueprints own configuration and presentation. Execute asset mutations serially, never during PIE, compile Blueprints with warnings as errors, save every edited package, then verify class, parent, references and dirty state. Never synthesize or patch .uasset files outside Unreal Editor.'),
      'ExtractionOpsAuthorityWorkflow': ('Preserve Extraction Ops server authority and raid-state invariants.', 'Treat clients as input and predicted-presentation producers only. The Editor Dedicated Process commits ammo, TargetData validation, damage, terminal activation, Threat waves, inventory commands, death drops, extraction and result snapshots. Match is Loading -> InRaid -> Completed; Run is InRaid -> Extracting -> Extracted or Dead or Abandoned; Terminal is Idle -> Activating -> Activated; Extraction is Locked -> Available -> Countdown -> Extracted or Cancelled. Use the owning PlayerState ASC for interaction abilities. Every Threat wave schedules once. Every item instance has one stable GUID and can be in exactly one world, container, backpack, extracted or lost location. Reject stale inventory versions and duplicate request IDs deterministically.'),
      'ExtractionOpsValidationWorkflow': ('Produce reproducible Week validation evidence for Extraction Ops.', 'Start from all Unreal processes closed. Build LyraEditor Win64 Development with D:/Software/UE_5.8 only. Run all ExtractionOps automation tests. Use an Editor Dedicated Process with NullRHI and two separate -game clients on L_ExtractionTest with B_ExtractionExperience and NumBots=0 before Threat spawns its own AI. Capture separate command lines and logs; verify two joins, Experience and GameFeature activation, raid start, replicated roles, disconnect isolation, and explicit client disconnect after server exit. Repeat once under 100 ms lag and once under 100 ms lag plus 5 percent packet loss. State clearly that this is Editor Dedicated Process evidence, not a packaged Server Target or Shipping performance result. Never access D:/Software/UE_5.8.1_Source.')
    }
    existing = list_skills()
    class_paths = []
    package_paths = []
    for name, spec in specs.items():
        expected = '/ExtractionOps/Skills/' + name + '.' + name + '_C'
        if expected in existing:
            if not update_skill(expected, spec[0], spec[1]):
                raise RuntimeError('failed to update ' + expected)
            class_path = expected
        else:
            class_path = create_skill(name, spec[0], spec[1])
            if not class_path:
                raise RuntimeError('failed to create ' + name)
        class_paths.append(class_path)
        package_paths.append('/ExtractionOps/Skills/' + name)
    if not save(package_paths):
        raise RuntimeError('failed to save project skills')
    return {'skills': get_skills(class_paths), 'savedPackages': package_paths}
